class Solution {
    public int projectionArea(int[][] grid){
        int n=grid.length,top=0;
        int[] rows=new int[n],columns=new int[n];
        for(int r=0;r<n;r++)for(int c=0;c<n;c++){
            if(grid[r][c]>0)top++;
            rows[r]=Math.max(rows[r],grid[r][c]);
            columns[c]=Math.max(columns[c],grid[r][c]);
        }
        return top+Arrays.stream(rows).sum()+Arrays.stream(columns).sum();
    }
}

code.kotlin:
class Solution {
    fun projectionArea(grid:Array<IntArray>):Int{
        val n=grid.size;
        var top=0;
        val rows=IntArray(n);
        val columns=IntArray(n);
        for(r in 0 until n)for(c in 0 until n){
            if(grid[r][c]>0)top++;
            rows[r]=maxOf(rows[r],grid[r][c]);
            columns[c]=maxOf(columns[c],grid[r][c])
        };
        return top+rows.sum()+columns.sum()
    }
}

